public class Main {
    static String[] play(long[] moves) {
        // Write your solution here
        // Return the 6 rows of the final board, top to bottom, e.g. "| | |X| | | | |"
        return new String[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] moves = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            moves[i] = (long) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (String row : play(moves)) sb.append(row).append("\n");
        System.out.print(sb);
    }
}
